styles.css:
/* Hlavička */
.graceart-header { border-bottom: 1px solid var(--wp--preset--color--line); }
.graceart-tagline { font-size: 12px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--wp--preset--color--muted); margin-top: 4px !important; }
.graceart-header .wp-block-site-title a { text-decoration: none; color: var(--wp--preset--color--ink); }
.graceart-header .wp-block-search__button { background: transparent !important; color: var(--wp--preset--color--ink) !important; border: 0 !important; padding: 8px !important; margin: 0 !important; min-width: 0; box-shadow: none !important; }
.graceart-header .wp-block-search__button svg { fill: currentColor; width: 24px; height: 24px; }

/* Úvodný banner */
.graceart-hero h1 { color: #fff; }
.graceart-hero .wp-block-button__link { min-width: 240px; }
.graceart-hero .is-style-outline .wp-block-button__link { border: 1px solid #fff; background: transparent; color: #fff; }

/* Štatistiky */
.graceart-stats { border-top: 1px solid var(--wp--preset--color--line); border-bottom: 1px solid var(--wp--preset--color--line); }
.graceart-stat-number { font-size: 40px !important; line-height: 1 !important; color: var(--wp--preset--color--brown); margin-bottom: 8px !important; }
.graceart-stat-label { font-size: 14px; color: var(--wp--preset--color--muted); margin-top: 0 !important; }

/* Kolekcie */
.graceart-categories .wp-block-image { margin-bottom: 16px; }
.graceart-category-name { font-size: 15px; font-weight: 500; letter-spacing: 0.12em; text-transform: uppercase; margin: 0 !important; }
.graceart-category-name a { color: var(--wp--preset--color--ink); text-decoration: none; }
.graceart-category-link { font-size: 13px; font-weight: 500; letter-spacing: 0.12em; text-transform: uppercase; margin-top: 4px !important; }
.graceart-category-link a { color: var(--wp--preset--color--brown); text-decoration: none; }

/* Produkty (zoznam) */
.woocommerce ul.products li.product .woocommerce-loop-product__title,
.wc-block-components-product-name,
.wp-block-post-title.wc-block-components-product-title { font-family: var(--wp--preset--font-family--jost) !important; font-size: 13px !important; font-weight: 500 !important; letter-spacing: 0.08em; text-transform: uppercase; color: var(--wp--preset--color--ink); }
.woocommerce ul.products li.product .price,
.wc-block-components-product-price { color: var(--wp--preset--color--brown) !important; font-size: 22px !important; font-weight: 400 !important; }
.woocommerce ul.products li.product a img { aspect-ratio: 1 / 1; object-fit: cover; border-radius: 2px; }
.woocommerce ul.products li.product .button { margin-top: 8px; }
.woocommerce span.onsale { background: var(--wp--preset--color--brown); }

/* Sekcia O mne */
.graceart-script { font-size: 46px !important; line-height: 1.1 !important; font-family: var(--wp--preset--font-family--great-vibes) !important; text-transform: none !important; letter-spacing: 0 !important; font-weight: 400 !important; }

/* Hodnotenia */
.graceart-review { border: 1px solid var(--wp--preset--color--line); border-radius: 2px; padding: 32px; height: 100%; box-sizing: border-box; }
.graceart-review-stars { color: var(--wp--preset--color--brown); letter-spacing: 4px; margin: 0 !important; }
.graceart-review-text { font-family: var(--wp--preset--font-family--cormorant) !important; font-style: italic; font-size: 26px !important; line-height: 1.3 !important; color: var(--wp--preset--color--ink); }
.graceart-review-name { font-size: 13px; font-weight: 500; letter-spacing: 0.12em; text-transform: uppercase; color: var(--wp--preset--color--muted); margin: 16px 0 0 !important; }

/* Hlavička kategórie (text vľavo, fotka vpravo) */
.graceart-cat-header { border-top: 1px solid var(--wp--preset--color--line); border-bottom: 1px solid var(--wp--preset--color--line); }
.graceart-cat-header .wp-block-column:last-child .wp-block-image,
.graceart-cat-header .wp-block-column:last-child .wp-block-image img { height: 100%; margin: 0; }
.graceart-cat-header .wp-block-query-title { margin: 0 0 12px; }
.graceart-cat-header .woocommerce-breadcrumb, .graceart-cat-header .wc-block-breadcrumbs { font-size: 14px; color: var(--wp--preset--color--muted); }
/* klasický nadpis a drobčeky WooCommerce pod hlavičkou kategórie skryť, aby neboli dvakrát */
.graceart-cat-archive .woocommerce-products-header,
.graceart-cat-archive > .woocommerce-breadcrumb,
.graceart-cat-archive .wp-block-woocommerce-legacy-template > .woocommerce-breadcrumb { display: none; }

/* Pätička */
.graceart-footer { border-top: 1px solid var(--wp--preset--color--line); }
.graceart-footer h2, .graceart-footer-heading { font-family: var(--wp--preset--font-family--jost) !important; font-size: 12px !important; font-weight: 600 !important; letter-spacing: 0.14em; text-transform: uppercase; color: var(--wp--preset--color--ink); margin-bottom: 12px !important; }
.graceart-footer p:not(.wp-block-site-title) { font-size: 14px; margin: 0 0 8px !important; }
.graceart-footer .wp-block-site-title { font-size: 46px !important; margin: 0 0 12px !important; }
.graceart-footer a { color: var(--wp--preset--color--ink); text-decoration: none; }
.graceart-footer a:hover { color: var(--wp--preset--color--brown); }
.graceart-copyright { border-top: 1px solid var(--wp--preset--color--line); font-size: 13px; }

@media (max-width: 781px) {
  .graceart-hero h1 { font-size: 36px !important; }
  .graceart-cat-header .wp-block-column:last-child { display: none; }
}
